source /etc/network_turbo 2>/dev/null; source /root/miniconda3/etc/profile.d/conda.sh && conda activate base && HF_ENDPOINT=https://hf-mirror.com REQUESTS_CA_BUNDLE=/etc/ssl/certs/ca-certificates.crt SSL_CERT_FILE=/etc/ssl/certs/ca-certificates.crt python -c "
from huggingface_hub import HfApi
api = HfApi()

# Try RedPajama repos
for repo in ['togethercomputer/RedPajama-Data-1T-Sample', 'togethercomputer/RedPajama-Data-V2']:
    try:
        files = api.list_repo_files(repo, repo_type='dataset')
        data_files = [f for f in files if any(f.endswith(e) for e in ('.parquet', '.json.gz', '.jsonl.gz', '.jsonl', '.zst'))]
        print(f'{repo}: {len(data_files)} data files')
        for f in data_files[:10]:
            print(f'  {f}')
    except Exception as e:
        print(f'{repo}: ERROR — {type(e).__name__}: {e}')
    print()

# Try Dolma
for repo in ['allenai/dolma', 'allenai/dolma3_pool']:
    try:
        files = api.list_repo_files(repo, repo_type='dataset')
        data_files = [f for f in files if any(f.endswith(e) for e in ('.parquet', '.json.gz', '.jsonl.gz', '.jsonl', '.zst'))]
        print(f'{repo}: {len(files)} total, {len(data_files)} data files')
        for f in data_files[:10]:
            print(f'  {f}')
        if not data_files:
            print(f'  All files: {files[:20]}')
    except Exception as e:
        print(f'{repo}: ERROR — {type(e).__name__}: {e}')
    print()
" 2>&1
